const screens=[['hub','Midpoint Hub'],['gym','Gym landing'],['gym-signup','Gym signup'],['gym-confirm','Gym next steps'],['gym-classes','Gym class calendar'],['gym-events','Gym event calendar'],['padel','Padel landing'],['padel-signup','Tenant signup'],['padel-confirm','Playtomic next steps'],['padel-events','Padel event calendar']];const nav=document.querySelector('#screens'),select=document.querySelector('#screen'),frame=document.querySelector('#preview');screens.forEach(([id,label],i)=>{nav.insertAdjacentHTML('beforeend',`<button data-page="${id}"><span>${String(i+1).padStart(2,'0')}</span>${label}</button>`);select.add(new Option(label,id))});function highlight(id){document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===id));select.value=id}function go(id){frame.src='screens.html#'+id;highlight(id)}nav.onclick=e=>{const b=e.target.closest('button');if(b)go(b.dataset.page)};select.onchange=()=>go(select.value);window.addEventListener('message',e=>{if(e.source===frame.contentWindow&&e.data?.screen)highlight(e.data.screen)});highlight('hub');